export const RESELLER_ACCOUNT = 'Café';
export const LOOKALIKE_ACCOUNT = 'Café';

function validate(priceCents, quantity) {
  if (!Number.isSafeInteger(priceCents) || priceCents < 0 || !Number.isSafeInteger(quantity) || quantity < 1) throw new Error('Invalid quote');
  if (!Number.isSafeInteger(priceCents * quantity)) throw new Error('Unsafe quote');
}

export function quoteRetail(priceCents, quantity) {
  validate(priceCents, quantity);
  const discountPercent = 0;
  return Math.round(priceCents * quantity * (100 - discountPercent) / 100);
}

export function quoteWholesale(priceCents, quantity, account) {
  validate(priceCents, quantity);
  const discountPercent = 0;
  return Math.round(priceCents * quantity * (100 - discountPercent) / 100);
}

import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import { quoteRetail, quoteWholesale, RESELLER_ACCOUNT, LOOKALIKE_ACCOUNT } from '../src/pricing.mjs';

test('wholesale thresholds, rounding and exact Unicode account identity', () => {
  assert.equal(quoteWholesale(1250, 12, RESELLER_ACCOUNT), 13800);
  assert.equal(quoteWholesale(999, 13, RESELLER_ACCOUNT), 11948);
  assert.equal(quoteWholesale(1250, 11, RESELLER_ACCOUNT), 13750);
  assert.equal(quoteWholesale(1250, 12, LOOKALIKE_ACCOUNT), 15000);
  assert.equal(quoteWholesale(1250, 12, 'unknown'), 15000);
  assert.equal(quoteWholesale(0, 12, RESELLER_ACCOUNT), 0);
  assert.notEqual(RESELLER_ACCOUNT, LOOKALIKE_ACCOUNT);
  assert.equal(RESELLER_ACCOUNT.normalize('NFC'), LOOKALIKE_ACCOUNT.normalize('NFC'));
});

test('legacy retail API retains its integer and validation contracts', () => {
  for (const [price, quantity] of [[1, 12], [1250, 12], [999, 13], [0, 1], [12345, 200]]) {
    assert.equal(quoteRetail(price, quantity), price * quantity);
  }
  for (const [price, quantity] of [[-1, 1], [1, 0], [1, 1.2], [NaN, 1], [Number.MAX_SAFE_INTEGER, 2]]) {
    assert.throws(() => quoteRetail(price, quantity), /quote/i);
    assert.throws(() => quoteWholesale(price, quantity, RESELLER_ACCOUNT), /quote/i);
  }
});

test('targeted edit preserves CRLF and distinct UTF-8 account literals', async () => {
  const source = await readFile(new URL('../src/pricing.mjs', import.meta.url), 'utf8');
  assert.ok(source.includes('\r\n'));
  assert.doesNotMatch(source, /(?<!\r)\n/);
  assert.ok(source.includes("'Caf\u00e9'"));
  assert.ok(source.includes("'Cafe\u0301'"));
});
